# Automated Test Suite generated by Agentic SDLC QA Agent (Google Gemini)
import os
import sys
sys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), "..")))
import pytest

import pytest
from app.utils import apply_discount

class TestApplyDiscount:

    # --- Valid Cases ---

    @pytest.mark.parametrize("price, discount_percent, expected_price", [
        # Standard discounts
        (100, 10, 90.00),
        (200, 25, 150.00),
        (50, 50, 25.00),
        (1000, 75, 250.00),
        # Zero discount
        (100, 0, 100.00),
        (0.01, 0, 0.01),
        # Full discount
        (100, 100, 0.00),
        (0.01, 100, 0.00),
        # Prices with decimals
        (99.99, 10, 89.99), # 99.99 * 0.9 = 89.991 -> 89.99
        (123.45, 20, 98.76), # 123.45 * 0.8 = 98.76
        # Discounts with decimals
        (100, 12.5, 87.50), # 100 * 0.875 = 87.50
        (200, 0.5, 199.00), # 200 * 0.995 = 199.00
        # Mixed decimal inputs
        (123.45, 10.5, 110.49), # 123.45 * (1 - 0.105) = 123.45 * 0.895 = 110.49075 -> 110.49
        # Large values
        (1000000, 1, 990000.00),
        (999999.99, 99.99, 100.00), # 999999.99 * (1 - 0.9999) = 99.999999 -> 100.00
        # Edge case: price is 0
        (0, 10, 0.00),
        (0, 99.99, 0.00),
    ])
    def test_apply_discount_valid_cases(self, price, discount_percent, expected_price):
        result = apply_discount(price, discount_percent)
        assert result == expected_price

    # --- Rounding specific tests (ROUND_HALF_UP) ---
    @pytest.mark.parametrize("price, discount_percent, expected_price", [
        # Cases ending in .xx5 should round up
        (10.00, 0.05, 10.00), # 10 * (1 - 0.0005) = 9.995 -> 10.00
        (100.00, 0.005, 100.00), # 100 * (1 - 0.00005) = 99.995 -> 100.00
        # Cases ending in .xx6 (or higher) should round up
        (100.00, 0.004, 100.00), # 100 * (1 - 0.00004) = 99.996 -> 100.00
        # Cases ending in .xx4 (or lower) should round down
        (10.00, 0.06, 9.99), # 10 * (1 - 0.0006) = 9.994 -> 9.99
        (100.00, 0.006, 99.99), # 100 * (1 - 0.00006) = 99.994 -> 99.99
    ])
    def test_apply_discount_rounding_half_up(self, price, discount_percent, expected_price):
        result = apply_discount(price, discount_percent)
        assert result == expected_price

    # --- Exception Cases (ValueError) ---

    @pytest.mark.parametrize("price, discount_percent, expected_error_message", [
        # Non-numeric inputs for price
        ("abc", 10, "Inputs must be numeric"),
        (None, 10, "Inputs must be numeric"),
        ([100], 10, "Inputs must be numeric"),
        # Non-numeric inputs for discount_percent
        (100, "xyz", "Inputs must be numeric"),
        (100, None, "Inputs must be numeric"),
        (100, {"discount": 10}, "Inputs must be numeric"),
        # Negative price
        (-100, 10, "Price cannot be negative"),
        (-0.01, 50, "Price cannot be negative"),
        # Discount out of range (less than 0)
        (100, -1, "Discount must be between 0 and 100"),
        (100, -0.01, "Discount must be between 0 and 100"),
        # Discount out of range (greater than 100)
        (100, 101, "Discount must be between 0 and 100"),
        (100, 100.01, "Discount must be between 0 and 100"),
    ])
    def test_apply_discount_invalid_inputs_raises_value_error(self, price, discount_percent, expected_error_message):
        with pytest.raises(ValueError) as excinfo:
            apply_discount(price, discount_percent)
        assert str(excinfo.value) == expected_error_message
